import os
import time
import six
from IQCommon import pandas as pd
from datetime import datetime
from IQCommon.logger import system_log
class AshareStorage(object):
    __doc__ = """
    市场信息存储
    """
    def __init__(self, path):
        self.latest_day = datetime.now().strftime('%Y%m%d')
        self.path = path
        self.load()
    def load(self):
        try:
            self._Ashare = pd.read_pickle(self.path)
        except Exception as ex:
            system_log.error('A股列表路径{}错误'.format(os.path.abspath(self.path)))
            raise FileNotFoundError('A股列表路径{}错误,请改正后重试'.format(os.path.abspath(self.path)))
    def reload(self):
        tmp_now = datetime.now().strftime('%Y%m%d')
        if self.latest_day != tmp_now:
            self.load()
            self.latest_day = tmp_now
            return None
    def get_Ashares(self, date=None):
        self.reload()
        if date is None:
            date = time.strftime('%Y%m%d', time.localtime())
        elif isinstance(date, six.string_types):
            date = int(date)
        now_df = self._Ashare.query('List_date <= %d & Delisting_date > %d' % (int(date), int(date)))
        stocks_all_list = list(now_df['stock_code'])
        return stocks_all_list
